import fs from 'node:fs';
import path from 'node:path';
import { activeBlogNumbers, retiredBlogRedirects } from './editorial-inventory.mjs';

const root = path.resolve(import.meta.dirname, '..');
const lines = [
  '# Generated by scripts/generate-redirects.mjs',
  '/index.html  /  301!',
  '/privacy.html  /privacy  301!',
  '/terms-and-conditions.html  /terms-and-conditions  301!',
  ...activeBlogNumbers.map(number => `/blogs/${number}.html  /blogs/${number}  301!`),
  ...[...retiredBlogRedirects].flatMap(([number, destination]) => [
    `/blogs/${number}.html  ${destination}  301!`,
    `/blogs/${number}  ${destination}  301!`
  ])
];

fs.writeFileSync(path.join(root, '_redirects'), `${lines.join('\n')}\n`);
console.log(`Generated _redirects with ${lines.length - 1} canonical URL rules.`);
